PROFILE Full

COMPONENT RigidBodyPhysics : 2

DEF RBC RigidBodyCollection {
  bodies [
    DEF A RigidBody {
      fixed TRUE
      position 0 5 0
      geometry DEF A_C CollidableShape {
        translation 0 5 0
        shape Shape {
          geometry Box {
            size 0.5 0.5 0.5
          }
        }
      }
    }
    DEF B RigidBody {
      position 1.499989 4.994172 0
      orientation 0 0 -1.00000000000727 0.0038853727364343
      linearVelocity -0.001234634 -0.3078499 0
      angularVelocity 0 0 -0.2052107
      geometry DEF B_C CollidableShape {
        translation 1.499989 4.994172 0
        rotation 0 0 -1.00000000000727 0.0038853727364343
        shape Shape {
          geometry Box {
            size 3 0.4 0.4
          }
        }
      }
    }
  ]
  joints DEF J SingleAxisHingeJoint {
    forceOutput [
      "body1AnchorPoint",
      "body2AnchorPoint",
      "angle",
      "angleRate"
    ]
    anchorPoint 0 5 0
    axis 0 0 1
    minAngle -1
    maxAngle 0.5
    body1 USE A
    body2 USE B
  }
}

